SELECT id, product_id, quantity, AVG(quantity) OVER w_grp AS quantity_avg_3, LAST_VALUE(quantity) IGNORE NULLS OVER w_running AS last_known_quantity, LEAD(quantity, 1) OVER (PARTITION BY product_id, store_id ORDER BY quantity, id) AS next_quantity, SUM(quantity) OVER (PARTITION BY product_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_quantity, SUM(quantity) OVER (ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_quantity_2 FROM inventory WINDOW w_grp AS (PARTITION BY store_id, product_id ORDER BY last_restock, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), w_running AS (PARTITION BY store_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
